1	import { BadRequestException, Body, Controller, Get, Post, Req, UseGuards } from '@nestjs/common';
2	import { JwtGuard } from '../auth/jwt.guard';
3	import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
4	import { SupabaseService } from '../supabase/supabase.service';
5	import { GeocodingService } from '../motoboy/geocoding.service';
6	import { PlanosService } from '../planos/planos.service';
7	
8	@Controller('restaurante')
9	export class OnboardingController {
10	  constructor(
11	    private supabase: SupabaseService,
12	    private geocoding: GeocodingService,
13	    private planos: PlanosService,
14	  ) {}
15	
16	  // Público (sem guard) — a wizard de cadastro mostra os planos antes do
17	  // usuário logar/criar conta, pra ele escolher já na primeira etapa.
18	  @Get('planos-disponiveis')
19	  planosDisponiveis() {
20	    return this.planos.listarPlanosAtivos('saas');
21	  }
22	
23	  // 1ª fase do cadastro: cria a loja só com nome + assinatura do plano
24	  // escolhido, e cobra a fatura do período atual na hora se o plano não tiver
25	  // trial. O resto do formulário (endereço, horários, tipo...) só é liberado
26	  // na wizard depois que essa fatura confirmar paga (ou, se for plano com
27	  // trial, direto). Idempotente: se o usuário já tem restaurante (reload no
28	  // meio do checkout), retorna o estado atual em vez de criar de novo.
29	  @Post('registrar-inicial')
30	  @UseGuards(JwtGuard)
31	  async registrarInicial(@Req() req: any, @Body() body: { name?: string; plano_id?: number }) {
32	    const userId: string = req.userId;
33	
34	    const { data: existing } = await this.supabase.client
35	      .from('restaurants')
36	      .select('id, name')
37	      .eq('user_id', userId)
38	      .maybeSingle();
39	
40	    let restaurant = existing;
41	    let precisaAssinar = false;
42	
43	    if (!restaurant) {
44	      if (!body.name?.trim()) throw new BadRequestException('Nome do estabelecimento é obrigatório.');
45	      if (!body.plano_id) throw new BadRequestException('Selecione um plano para continuar.');
46	
47	      const slug = body.name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
48	
49	      const { data: novo, error } = await this.supabase.client
50	        .from('restaurants')
51	        .insert({ name: body.name, user_id: userId, slug })
52	        .select('id, name')
53	        .single();
54	      if (error) throw error;
55	      restaurant = novo;
56	      precisaAssinar = true;
57	    } else if (body.plano_id) {
58	      // Já tem loja (voltou nesse passo, ou reload) — só reassina se o plano
59	      // escolhido agora for DIFERENTE do que já está na assinatura. Sem essa
60	      // checagem, trocar de plano na wizard e clicar Continuar de novo
61	      // ignorava a nova escolha e reaproveitava fatura/trial do plano antigo.
62	      const { assinatura } = await this.planos.buscarAssinaturaPorRestaurante(restaurant.id);
63	      precisaAssinar = assinatura.plano_id !== body.plano_id;
64	
65	      if (precisaAssinar) {
66	        // Role só eleva pra restaurant_owner no /finalizar — se ainda é
67	        // 'customer', o usuário está só comparando planos, nada foi pago.
68	        // Cancela fatura pendente do plano anterior pra não ficar presa
69	        // bloqueando o plano novo escolhido (ex: trial). Restrito a esse
70	        // estado pra não deixar um dono já pagante cancelar dívida real só
71	        // reenviando outro plano_id nesse endpoint.
72	        const { data: perfil } = await this.supabase.client
73	          .from('user_profiles').select('role').eq('id', userId).maybeSingle();
74	        if (perfil?.role !== 'restaurant_owner') {
75	          await this.supabase.client
76	            .from('plano_faturas')
77	            .update({ status: 'cancelada', atualizado_em: new Date().toISOString() })
78	            .eq('assinatura_id', assinatura.id)
79	            .in('status', ['pendente', 'vencida']);
80	        }
81	      }
82	    }
83	
84	    let status: { fatura_pendente_id: number | null };
85	    if (precisaAssinar) {
86	      // precisaAssinar só fica true quando body.plano_id já foi validado como
87	      // presente (loja nova) ou veio no body pra decidir a troca (loja existente).
88	      const planoId = body.plano_id as number;
89	      const plano = await this.planos.buscarPlano(planoId);
90	      await this.planos.atribuirAssinatura({ restaurantId: restaurant.id }, planoId);
91	
92	      // Sem trial: gera (forçado) a fatura do período atual pra cobrar já no
93	      // cadastro. Com trial, não força nada — fica pra próxima renovação natural.
94	      const temTrial = (plano.trial_dias ?? 0) > 0;
95	      status = await this.planos.sincronizarPeriodo({ restaurantId: restaurant.id }, !temTrial);
96	    } else {
97	      status = await this.planos.sincronizarPeriodo({ restaurantId: restaurant.id });
98	    }
99	
100	    if (!status.fatura_pendente_id) {
101	      return { restaurant, precisa_pagamento: false, fatura: null };
102	    }
103	
104	    const fatura = await this.planos.buscarFaturaDoRestaurante(restaurant.id, status.fatura_pendente_id);
105	    return { restaurant, precisa_pagamento: true, fatura };
106	  }
107	
108	  // 2ª fase: completa o cadastro (endereço, horários, tipo de estabelecimento)
109	  // e eleva o role pra restaurant_owner — só chamada depois que a wizard
110	  // liberou o formulário (plano pago ou em trial).
111	  @Post('finalizar')
112	  @UseGuards(RestaurantOwnerGuard)
113	  async finalizar(
114	    @Req() req: any,
115	    @Body()
116	    body: {
117	      name?: string;
118	      address?: string;
119	      state?: string;
120	      city?: string;
121	      neighborhood?: string;
122	      cep?: string;
123	      business_hours?: object;
124	      type_id?: number;
125	    },
126	  ) {
