1	import { BadRequestException, Body, Controller, Get, Post, Req, UseGuards } from '@nestjs/common';
2	import { JwtGuard } from '../auth/jwt.guard';
3	import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
4	import { SupabaseService } from '../supabase/supabase.service';
5	import { GeocodingService } from '../motoboy/geocoding.service';
6	import { PlanosService } from '../planos/planos.service';
7	import { UsuariosService } from '../usuarios/usuarios.service';
8	
9	@Controller('restaurante')
10	export class OnboardingController {
11	  constructor(
12	    private supabase: SupabaseService,
13	    private geocoding: GeocodingService,
14	    private planos: PlanosService,
15	    private usuarios: UsuariosService,
16	  ) {}
17	
18	  // Público (sem guard) — a wizard de cadastro mostra os planos antes do
19	  // usuário logar/criar conta, pra ele escolher já na primeira etapa.
20	  @Get('planos-disponiveis')
21	  planosDisponiveis() {
22	    return this.planos.listarPlanosAtivos('saas');
23	  }
24	
25	  // 1ª fase do cadastro: cria a loja só com nome + assinatura do plano
26	  // escolhido, e cobra a fatura do período atual na hora se o plano não tiver
27	  // trial. O resto do formulário (endereço, horários, tipo...) só é liberado
28	  // na wizard depois que essa fatura confirmar paga (ou, se for plano com
29	  // trial, direto). Idempotente: se o usuário já tem restaurante (reload no
30	  // meio do checkout), retorna o estado atual em vez de criar de novo.
31	  @Post('registrar-inicial')
32	  @UseGuards(JwtGuard)
33	  async registrarInicial(@Req() req: any, @Body() body: { name?: string; plano_id?: number }) {
34	    const userId: string = req.userId;
35	
36	    const { data: existing } = await this.supabase.client
37	      .from('restaurants')
38	      .select('id, name')
39	      .eq('user_id', userId)
40	      .maybeSingle();
41	
42	    let restaurant = existing;
43	    let precisaAssinar = false;
44	
45	    if (!restaurant) {
46	      if (!body.name?.trim()) throw new BadRequestException('Nome do estabelecimento é obrigatório.');
47	      if (!body.plano_id) throw new BadRequestException('Selecione um plano para continuar.');
48	
49	      const slug = body.name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
50	
51	      const { data: novo, error } = await this.supabase.client
52	        .from('restaurants')
53	        .insert({ name: body.name, user_id: userId, slug })
54	        .select('id, name')
55	        .single();
56	      if (error) throw error;
57	      restaurant = novo;
58	      precisaAssinar = true;
59	    } else if (body.plano_id) {
60	      // Já tem loja (voltou nesse passo, ou reload) — só reassina se o plano
61	      // escolhido agora for DIFERENTE do que já está na assinatura. Sem essa
62	      // checagem, trocar de plano na wizard e clicar Continuar de novo
63	      // ignorava a nova escolha e reaproveitava fatura/trial do plano antigo.
64	      const { assinatura } = await this.planos.buscarAssinaturaPorRestaurante(restaurant.id);
65	      precisaAssinar = assinatura.plano_id !== body.plano_id;
66	
67	      if (precisaAssinar) {
68	        // Role só eleva pra restaurant_owner no /finalizar — se ainda é
69	        // 'customer', o usuário está só comparando planos, nada foi pago.
70	        // Cancela fatura pendente do plano anterior pra não ficar presa
71	        // bloqueando o plano novo escolhido (ex: trial). Restrito a esse
72	        // estado pra não deixar um dono já pagante cancelar dívida real só
